import { CATEGORY_SLUGS } from "./slugs"
import type { CategoryExtendedMeta } from "./types"

type CategoryRow = readonly [
  title: string,
  description: string,
  intro: string,
  guide: string,
  faq1q: string,
  faq1a: string,
  faq2q: string,
  faq2a: string,
  faq3q: string,
  faq3a: string,
]

function buildCategories(rows: readonly CategoryRow[]): Record<string, CategoryExtendedMeta> {
  return Object.fromEntries(
    CATEGORY_SLUGS.map((slug, i) => {
      const [title, description, intro, guide, faq1q, faq1a, faq2q, faq2a, faq3q, faq3a] = rows[i]
      return [
        slug,
        {
          title,
          description,
          intro,
          guide,
          faq: [
            { q: faq1q, a: faq1a },
            { q: faq2q, a: faq2a },
            { q: faq3q, a: faq3a },
          ],
        },
      ]
    }),
  ) as Record<string, CategoryExtendedMeta>
}

